parameters.text:
=Contenido de artículos del mes (Top {{ $json.matches.length }} más relevantes):

{{ $json.matches.map((item, idx) => `
---
Artículo ${idx + 1}:
Título: ${item.metadata.titulo || 'N/A'}
Autor: ${item.metadata.autor || 'N/A'}
Tema: ${item.metadata.grupo_investigador || 'N/A'}
Fecha: ${item.metadata.fecha_publicacion || 'N/A'}
Relevancia: ${(item.score * 100).toFixed(1)}%
Contenido:
${item.metadata.contenido || item.metadata.resumen || 'N/A'}
`).join('
') }}

parameters.message:
=<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{ $json.titulo_newsletter }}</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 0 auto; background-color: #f4f4f4; }
        .container { background-color: #ffffff; padding: 0; margin: 20px auto; border-radius: 8px; overflow: hidden; box-shadow: 0 0 20px rgba(0,0,0,0.1); }
        .header-image { width: 100%; height: auto; display: block; }
        .content { padding: 40px; }
        .greeting { font-size: 18px; color: #0066cc; margin-bottom: 20px; }
        .article { margin-bottom: 40px; }
        .article h2 { color: #0066cc; border-bottom: 2px solid #0066cc; padding-bottom: 10px; }
        .divider { border: 0; border-top: 2px solid #e0e0e0; margin: 30px 0; }
        .spanish-section { background-color: #f9f9f9; padding: 20px; border-left: 4px solid #0066cc; margin-top: 30px; }
        .footer { background-color: #333; color: #fff; text-align: center; padding: 20px; font-size: 12px; }
        .footer a { color: #0066cc; text-decoration: none; }
    </style>
</head>
<body>
    <div class="container">
        {{ $json.imagen_url ? '<img src="' + $json.imagen_url + '" alt="Newsletter Header" class="header-image">' : '' }}

        <div class="content">
            <div class="greeting">
                <strong>Hola {{ $json.nombre }},</strong>
            </div>

            <p>Nos complace presentarte el newsletter mensual de {{ $now.minus({ months: 1 }).toFormat('MMMM yyyy') }} con los últimos hallazgos de nuestro equipo de investigación.</p>

            <div class="article">
                {{ $json.articulo_html }}
            </div>

            <hr class="divider">

            <div class="spanish-section">
                <h3 style="margin-top: 0; color: #0066cc;">🌎 Versión en Español</h3>
                {{ $json.snippet_espanol }}
            </div>
        </div>

        <div class="footer">
            <p>Este newsletter fue enviado a {{ $json.email }}</p>
            <p>Investigador asignado: {{ $json.grupo_investigador }}</p>
            <p><a href="https://nuestro-sitio.com/unsubscribe?email={{ $json.email }}">Cancelar suscripción</a> | <a href="https://nuestro-sitio.com/preferences">Preferencias</a></p>
            <p>&copy; {{ $now.year }} Everest Brothers Research. Todos los derechos reservados.</p>
        </div>
    </div>
</body>
</html>
